mapper.select:
SELECT EXISTS (
    SELECT 1
      FROM ABUSE_REPORT_IMPACT i
      JOIN ABUSE_REPORT r ON r.ABR_SN = i.ABR_SN
     WHERE i.ABR_IMP_REF_TYPE_CD = #{referenceTypeCode}
       AND i.ABR_IMP_REF_SN = #{referenceSn}
       AND i.ABR_SN != #{excludedReportSn}
       AND i.ABR_IMP_STATUS_CD = 'APPLIED'
       AND r.ABR_STATUS_CD IN (#{receivedStatusCode}, #{processingStatusCode})
)
